begin;

create table runtime.reconciliationevidence(
  id text primary key,
  source_count bigint not null,
  target_count bigint not null,
  source_amount bigint,
  target_amount bigint,
  difference bigint not null,
  checked_at timestamptz not null
);
create table runtime.reconciliationhash(
  id text primary key,
  source_hash char(64) not null,
  target_hash char(64) not null,
  checked_at timestamptz not null
);

insert into runtime.reconciliationevidence values
('organization',(select count(*) from public.tenants)+(select count(*) from public.enterprises)+(select count(*) from public.malls)+(select count(*) from public.departments)+(select count(*) from public.distributors)+1,(select count(*) from organization.organization),null,null,
 (select count(*) from organization.organization)-((select count(*) from public.tenants)+(select count(*) from public.enterprises)+(select count(*) from public.malls)+(select count(*) from public.departments)+(select count(*) from public.distributors)+1),clock_timestamp()),
('member',(select count(*) from public.members source where not exists(select 1 from public.member_login_aliases alias where alias.member_id=source.id and alias.provider='test')),
 (select count(*) from member.profile),null,null,(select count(*) from member.profile)-(select count(*) from public.members source where not exists(select 1 from public.member_login_aliases alias where alias.member_id=source.id and alias.provider='test')),clock_timestamp()),
('membership',(select count(*) from public.memberships source where exists(select 1 from member.profile profile where profile.id=source.member_id)),
 (select count(*) from member.membership),null,null,(select count(*) from member.membership)-(select count(*) from public.memberships source where exists(select 1 from member.profile profile where profile.id=source.member_id)),clock_timestamp()),
('product',(select count(*) from public.products where is_test=false),(select count(*) from catalog.product),null,null,(select count(*) from catalog.product)-(select count(*) from public.products where is_test=false),clock_timestamp()),
('sku',(select count(*) from public.skus source join public.products product on product.id=source.product_id where product.is_test=false),(select count(*) from catalog.sku),null,null,(select count(*) from catalog.sku)-(select count(*) from public.skus source join public.products product on product.id=source.product_id where product.is_test=false),clock_timestamp()),
('inventory',(select count(*) from inventory.stock_items source join public.products product on product.id=(select sku.product_id from public.skus sku where sku.id=source.sku_id) where product.is_test=false),(select count(*) from inventory.stockitem),(select coalesce(sum(source.onhand),0) from inventory.stock_items source join public.skus sku on sku.id=source.sku_id join public.products product on product.id=sku.product_id where product.is_test=false),(select coalesce(sum(onhand),0) from inventory.stockitem),(select coalesce(sum(onhand),0) from inventory.stockitem)-(select coalesce(sum(source.onhand),0) from inventory.stock_items source join public.skus sku on sku.id=source.sku_id join public.products product on product.id=sku.product_id where product.is_test=false),clock_timestamp()),
('order',(select count(*) from public.orders),(select count(*) from ordering.orderrecord),(select coalesce(sum(payable_cents),0) from public.orders),(select coalesce(sum(total_minor),0) from ordering.orderrecord),(select coalesce(sum(total_minor),0) from ordering.orderrecord)-(select coalesce(sum(payable_cents),0) from public.orders),clock_timestamp()),
('payment',(select count(*) from public.payments where status in('succeeded','refunded','closed')),(select count(*) from payment.payment),(select coalesce(sum(amount_cents),0) from public.payments where status in('succeeded','refunded','closed')),(select coalesce(sum(amount_minor),0) from payment.payment),(select coalesce(sum(amount_minor),0) from payment.payment)-(select coalesce(sum(amount_cents),0) from public.payments where status in('succeeded','refunded','closed')),clock_timestamp()),
('benefit',(select count(*) from public.welfare_accounts),(select count(*) from benefit.account),(select coalesce(sum(balance_cents),0) from public.welfare_accounts),(select coalesce(sum(amount_minor),0) from benefit.entry),(select coalesce(sum(amount_minor),0) from benefit.entry)-(select coalesce(sum(balance_cents),0) from public.welfare_accounts),clock_timestamp()),
('voucher',(select count(*) from public.vouchers),(select count(*) from voucher.voucher),(select coalesce(sum(remaining_cents),0) from public.vouchers),(select coalesce(sum(remaining_minor),0) from voucher.voucher),(select coalesce(sum(remaining_minor),0) from voucher.voucher)-(select coalesce(sum(remaining_cents),0) from public.vouchers),clock_timestamp()),
('financejournal',(select count(*) from public.finance_journals)+(select count(*) from public.account_ledgers),(select count(*) from finance.journal),null,null,(select count(*) from finance.journal)-((select count(*) from public.finance_journals)+(select count(*) from public.account_ledgers)),clock_timestamp()),
('financeentry',(select count(*) from public.finance_journal_entries)+2*(select count(*) from public.account_ledgers),(select count(*) from finance.entry),(select coalesce(sum(amount_cents),0) from public.finance_journal_entries)+2*(select coalesce(sum(amount_cents),0) from public.account_ledgers),(select coalesce(sum(amount_minor),0) from finance.entry),(select coalesce(sum(amount_minor),0) from finance.entry)-((select coalesce(sum(amount_cents),0) from public.finance_journal_entries)+2*(select coalesce(sum(amount_cents),0) from public.account_ledgers)),clock_timestamp()),
('audit',(select count(*) from public.audit_logs),(select count(*) from audit.record),null,null,(select count(*) from audit.record)-(select count(*) from public.audit_logs),clock_timestamp());

