('partner.relationship',(select count(*) from public.supplier_brand_bindings)+(select count(*) from public.brand_store_bindings),(select count(*) from partner.relationship),null,null,(select count(*) from partner.relationship)-((select count(*) from public.supplier_brand_bindings)+(select count(*) from public.brand_store_bindings)),clock_timestamp()),
('partner.agreement',(select count(*) from public.mall_supplier_agreements)+(select count(*) from public.mall_brand_authorizations),(select count(*) from partner.agreement),null,null,(select count(*) from partner.agreement)-((select count(*) from public.mall_supplier_agreements)+(select count(*) from public.mall_brand_authorizations)),clock_timestamp()),
('catalog.pool',(select count(*) from public.catalog_pools),(select count(*) from catalog.pool),null,null,(select count(*) from catalog.pool)-(select count(*) from public.catalog_pools),clock_timestamp()),
('catalog.poolitem',(select count(*) from public.catalog_pool_items source where exists(select 1 from catalog.sku target where target.id=source.sku_id)),(select count(*) from catalog.poolitem),null,null,(select count(*) from catalog.poolitem)-(select count(*) from public.catalog_pool_items source where exists(select 1 from catalog.sku target where target.id=source.sku_id)),clock_timestamp()),
('catalog.poolbinding',(select count(*) from public.mall_catalog_pool_bindings),(select count(*) from catalog.poolbinding),null,null,(select count(*) from catalog.poolbinding)-(select count(*) from public.mall_catalog_pool_bindings),clock_timestamp()),
('catalog.governance',(select count(*) from public.catalog_supplier_category_mappings)+(select count(*) from public.catalog_classification_rules)+(select count(*) from public.catalog_review_queue source join public.products product on product.id=source.product_id where product.is_test=false),(select count(*) from catalog.suppliercategory)+(select count(*) from catalog.classificationrule)+(select count(*) from catalog.review),null,null,((select count(*) from catalog.suppliercategory)+(select count(*) from catalog.classificationrule)+(select count(*) from catalog.review))-((select count(*) from public.catalog_supplier_category_mappings)+(select count(*) from public.catalog_classification_rules)+(select count(*) from public.catalog_review_queue source join public.products product on product.id=source.product_id where product.is_test=false)),clock_timestamp()),
