('checkout.address',(select count(*) from public.delivery_addresses source join public.members legacy on legacy.user_id=source.user_id where exists(select 1 from member.profile target where target.id=legacy.id)),(select count(*) from checkout.address),null,null,(select count(*) from checkout.address)-(select count(*) from public.delivery_addresses source join public.members legacy on legacy.user_id=source.user_id where exists(select 1 from member.profile target where target.id=legacy.id)),clock_timestamp()),
