('ordering.review',(select count(*) from public.after_sale_review_actions),(select count(*) from ordering.reviewaction),null,null,(select count(*) from ordering.reviewaction)-(select count(*) from public.after_sale_review_actions),clock_timestamp()),
('verification.session',(select count(*) from public.member_code_challenges source where exists(select 1 from member.profile target where target.id=source.member_id))+(select count(*) from public.voucher_redemptions),(select count(*) from verification.session),null,null,(select count(*) from verification.session)-((select count(*) from public.member_code_challenges source where exists(select 1 from member.profile target where target.id=source.member_id))+(select count(*) from public.voucher_redemptions)),clock_timestamp()),
